{"research_date": "2026-09-10", "pairs": [{"pair_id": "conflict_827625fc9e3b855d60f1a9f0", "claim_ids": ["claim_d119bc054e534700289d9dc8", "claim_f121c6ae83cb279d26a53bd6"], "query_ids": ["q_235"], "claims": [{"claim_id": "claim_d119bc054e534700289d9dc8", "quote": "Tariffs take effect this week, creating pricing instability across the auto industry.", "url": "https://www.facebook.com/quartznews/posts/hyundai-is-weighing-a-massive-expansion-of-its-georgia-car-plant-citing-tariffs-/1419057173423430", "kind": "search_snippet", "publisher_type": "secondary_or_unverified_publisher", "fields": {"tariff_program": "Tariffs", "effective_date": "this week"}}, {"claim_id": "claim_f121c6ae83cb279d26a53bd6", "quote": "The 15% tariff applied to South Korean imports is increasing the economic incentive for local production expansion.", "url": "https://finance.biggo.com/news/7c816f70-187d-4f54-84d6-c8c8f26bacb6", "kind": "full_document", "publisher_type": "secondary_or_unverified_publisher", "fields": {"duty_rate": "15%"}}]}, {"pair_id": "conflict_f859327e3bbffd4df395d307", "claim_ids": ["claim_91e310682eb7020e1489d176", "claim_9312f7b923c808a1a6a60acb"], "query_ids": ["q_236"], "claims": [{"claim_id": "claim_91e310682eb7020e1489d176", "quote": "To avoid U.S. tariffs, automakers like Tesla and Hyundai are moving battery and component manufacturing to Vietnam, Malaysia, and Mexico.", "url": "https://blogs.tradlinx.com/shifting-gears-how-tariffs-and-trade-wars-are-rewiring-the-automotive-supply-chain", "kind": "search_snippet", "publisher_type": "secondary_or_unverified_publisher", "fields": {"company": "Tesla"}}, {"claim_id": "claim_9312f7b923c808a1a6a60acb", "quote": "To avoid U.S. tariffs, automakers like Tesla and Hyundai are moving battery and component manufacturing to Vietnam, Malaysia, and Mexico.", "url": "https://blogs.tradlinx.com/shifting-gears-how-tariffs-and-trade-wars-are-rewiring-the-automotive-supply-chain", "kind": "search_snippet", "publisher_type": "secondary_or_unverified_publisher", "fields": {}}]}, {"pair_id": "conflict_bcf85b67eafad54fed67ef62", "claim_ids": ["claim_6ca3cfd95d9ca149f551f677", "claim_b3e64e31e04f93c56b117540"], "query_ids": ["q_236"], "claims": [{"claim_id": "claim_6ca3cfd95d9ca149f551f677", "quote": "President Joe Biden on Tuesday raised tariffs in an effort to protect American electric vehicle and solar panel industries from cheap Chinese imports, ramping up an ongoing trade war between the two global superpowers that could impact Georgia’s burgeoning clean tech sector.", "url": "https://www.ajc.com/news/business/how-will-new-chinese-tariffs-affect-georgia-business-its-complicated/7XZZOOZMUVH6TPWP2ZJY74GIFQ", "kind": "full_document", "publisher_type": "secondary_or_unverified_publisher", "fields": {"tariff_program": "raised tariffs", "affected_product": "electric vehicle and solar panel industries"}}, {"claim_id": "claim_b3e64e31e04f93c56b117540", "quote": "The Democratic president quadrupled tariffs on Chinese EVs and sharply increased import taxes on solar panels and raw materials like semiconductors that are used to produce plug-in cars.", "url": "https://www.ajc.com/news/business/how-will-new-chinese-tariffs-affect-georgia-business-its-complicated/7XZZOOZMUVH6TPWP2ZJY74GIFQ", "kind": "full_document", "publisher_type": "secondary_or_unverified_publisher", "fields": {"tariff_program": "quadrupled tariffs", "affected_product": "Chinese EVs"}}]}, {"pair_id": "conflict_e9f6a34bfb55bfa6a547d81b", "claim_ids": ["claim_3bb5982d357506707d154214", "claim_7ca957ed2a8d8c86c801dd0e"], "query_ids": ["q_238"], "claims": [{"claim_id": "claim_3bb5982d357506707d154214", "quote": "Presently, most batteries and critical battery materials are produced in China, but American technological innovation and industrial policy have put the nation in a strategic position to lead the next generation of battery development.", "url": "https://www.c2es.org/document/securing-the-critical-battery-materials-supply-chain-in-the-southeast-united-states", "kind": "full_document", "publisher_type": "secondary_or_unverified_publisher", "fields": {"country_of_origin": "China", "exporting_country": "China"}}, {"claim_id": "claim_7ca957ed2a8d8c86c801dd0e", "quote": "The top two global battery suppliers are Chinese, with China having produced more than 70 percent of all EV batteries ever manufactured.", "url": "https://www.c2es.org/document/securing-the-critical-battery-materials-supply-chain-in-the-southeast-united-states", "kind": "full_document", "publisher_type": "secondary_or_unverified_publisher", "fields": {"country_of_origin": "China", "exporting_country": "China"}}]}, {"pair_id": "conflict_6957538c5a7fcd195958ffd0", "claim_ids": ["claim_907ba6bf60e5e5986042718f", "claim_9af3e5b325880203e1bdd631"], "query_ids": ["q_238"], "claims": [{"claim_id": "claim_907ba6bf60e5e5986042718f", "quote": "New requirements include that the cars must be assembled in North America and that materials and critical minerals in the battery must come from the U.S. or a country with a free trade agreement with the U.S.", "url": "https://www.coxautoinc.com/mobility/wp-content/uploads/sites/11/2022/09/EV_Battery_Whitepaper.pdf", "kind": "full_document", "publisher_type": "secondary_or_unverified_publisher", "fields": {}}, {"claim_id": "claim_9af3e5b325880203e1bdd631", "quote": "China controls nearly three-quarters of the market for the raw materials that go into these batteries.", "url": "https://www.coxautoinc.com/mobility/wp-content/uploads/sites/11/2022/09/EV_Battery_Whitepaper.pdf", "kind": "full_document", "publisher_type": "secondary_or_unverified_publisher", "fields": {"exporting_country": "China"}}]}, {"pair_id": "conflict_3af51f330c4d4854504671ee", "claim_ids": ["claim_5bb5d449626fbc4790742ef5", "claim_aeec262d58c34f96687a4bd4"], "query_ids": ["q_240"], "claims": [{"claim_id": "claim_5bb5d449626fbc4790742ef5", "quote": "the expected October 15 end of the tariff truce between the US and China that temporarily brought rates down from the staggering peak of 145% to a more reasonable 30%.", "url": "https://www.ajot.com/premium/ajot-china-imports-surge-ahead-of-tariff-deadlines", "kind": "full_document", "publisher_type": "secondary_or_unverified_publisher", "fields": {"tariff_program": "tariff truce", "duty_rate": "30%", "effective_date": "October 15", "expiration_date": "October 15"}}, {"claim_id": "claim_aeec262d58c34f96687a4bd4", "quote": "frontloading in response to the 30% temporary tariff rate on Chinese imports set to expire in mid-October.", "url": "https://www.ajot.com/premium/ajot-china-imports-surge-ahead-of-tariff-deadlines", "kind": "full_document", "publisher_type": "secondary_or_unverified_publisher", "fields": {"tariff_program": "temporary tariff rate", "duty_rate": "30%", "expiration_date": "mid-October"}}]}, {"pair_id": "conflict_1c6be60b9f5d777d1910f6fd", "claim_ids": ["claim_4fe721ce28109ed4bbdef5d7", "claim_8ce1add578a55174ca86d095"], "query_ids": ["q_241"], "claims": [{"claim_id": "claim_4fe721ce28109ed4bbdef5d7", "quote": "GPA saw a 7.5% decline in 2025 volume at the Port of Brunswick, its Roll-On/Roll-Off port for autos and heavy machinery.", "url": "https://www.savannahnow.com/story/news/local/2026/01/28/georgia-ports-authority-weathers-year-of-tariffs-with-strong-performance/88382339007", "kind": "search_snippet", "publisher_type": "secondary_or_unverified_publisher", "fields": {"company": "GPA", "facility": "Port of Brunswick", "tariff_program": "tariffs"}}, {"claim_id": "claim_8ce1add578a55174ca86d095", "quote": "Shipments of autos and machinery through the Port of Brunswick fell 14.3%. For the fiscal year to date, volumes have declined 11.8% to 132,918", "url": "https://www.bizjournals.com/atlanta/news/2025/10/01/georgia-ports-august-tariffs.html", "kind": "search_snippet", "publisher_type": "secondary_or_unverified_publisher", "fields": {"company": "Port of Brunswick", "duty_rate": "14.3%"}}]}, {"pair_id": "conflict_48668629a4f9200e3d8ef700", "claim_ids": ["claim_0b79b1d31aa3506dc4d14bf3", "claim_51992e560d852026aae487e5"], "query_ids": ["q_242"], "claims": [{"claim_id": "claim_0b79b1d31aa3506dc4d14bf3", "quote": "A 25% tariff took effect on April 3, 2025, for imported automobiles and light trucks, and on May 3, 2025, for specific auto parts such as engines, transmissions, and electrical components.", "url": "https://www.ghy.com/trade-compliance/us-to-apply-a-25-tariff-on-imports-of-autos-and-parts", "kind": "full_document", "publisher_type": "secondary_or_unverified_publisher", "fields": {"tariff_program": "Proclamation 10908", "effective_date": "April 3, 2025"}}, {"claim_id": "claim_51992e560d852026aae487e5", "quote": "The purpose of this message is to provide guidance on the 25 percent duty on imports of certain automobile parts from all countries effective 12:01 a.m. ET on May 3, 2025.", "url": "https://content.govdelivery.com/accounts/USDHSCBP/bulletins/3de7ef9", "kind": "full_document", "publisher_type": "secondary_or_unverified_publisher", "fields": {"tariff_program": "Section 232", "duty_rate": "25 percent", "effective_date": "May 3, 2025"}}]}, {"pair_id": "conflict_c080e372e564bb0b6c33dd96", "claim_ids": ["claim_412020137629721ca450ce54", "claim_97f7e1cc80cf2984ca879c23"], "query_ids": ["q_242"], "claims": [{"claim_id": "claim_412020137629721ca450ce54", "quote": "Only auto parts for passenger vehicles and light trucks, as defined by Executive Order 14257, issued April 2, 2025, and subject to Section 232 duties as of May 3, 2025, are not subject to the reciprocal duties effective April 5, 2025, pursuant to heading 9903.01.33, HTSUS.", "url": "https://www.cbp.gov/trade/programs-administration/entry-summary/section-232-additional-faqs-autos", "kind": "full_document", "publisher_type": "official_trade_authority", "fields": {"tariff_program": "Section 232 duties", "affected_product": "auto parts for passenger vehicles and light trucks", "hts_code": "9903.01.33, HTSUS", "effective_date": "May 3, 2025"}}, {"claim_id": "claim_97f7e1cc80cf2984ca879c23", "quote": "Heading 9903.01.33, HTSUS, exempting products subject to Section 232 from the reciprocal tariffs, applies to auto parts for passenger vehicles and light trucks.", "url": "https://www.cbp.gov/trade/programs-administration/entry-summary/section-232-additional-faqs-autos", "kind": "full_document", "publisher_type": "official_trade_authority", "fields": {"tariff_program": "reciprocal tariffs", "affected_product": "auto parts for passenger vehicles and light trucks", "hts_code": "9903.01.33, HTSUS"}}]}, {"pair_id": "conflict_e185222be00af5f917943fa5", "claim_ids": ["claim_60bd21591628a7a8e4991de3", "claim_f6ac4b1d7acd7bd3895f7f02"], "query_ids": ["q_242"], "claims": [{"claim_id": "claim_60bd21591628a7a8e4991de3", "quote": "Commercial vehicles, such as sedans, sport utility vehicles, crossover utility vehicles, minivans, cargo vans and light trucks, provided for in heading 9903.94.01, HTSUS, are subject to the Section 232 duties pursuant to the Proclamation.", "url": "https://www.cbp.gov/trade/programs-administration/entry-summary/section-232-additional-faqs-autos", "kind": "full_document", "publisher_type": "official_trade_authority", "fields": {"tariff_program": "Section 232 duties", "affected_product": "Commercial vehicles, such as sedans, sport utility vehicles, crossover utility vehicles, minivans, cargo vans and light trucks", "hts_code": "9903.94.01, HTSUS"}}, {"claim_id": "claim_f6ac4b1d7acd7bd3895f7f02", "quote": "The Section 232 automobile measures apply to all imported parts of passenger vehicles (sedans, sport utility vehicles, crossover utility vehicles, minivans, and cargo vans) and light trucks classifiable in the provisions of the HTSUS enumerated in subdivision (g) or meet the criteria in subdivision (h), as described under headings 9903.94.05 and 9903.94.06, respectively.", "url": "https://content.govdelivery.com/accounts/USDHSCBP/bulletins/3de7ef9", "kind": "full_document", "publisher_type": "secondary_or_unverified_publisher", "fields": {"affected_product": "parts of passenger vehicles (sedans, sport utility vehicles, crossover utility vehicles, minivans, and cargo vans) and light trucks", "chapter_99_code": "9903.94.05"}}]}]}

